{* Code generated by packages/kit-compose/src/server-organisms.ts from packages/compose-gen/specs (compose-gen organism emitters on kit-compose). DO NOT EDIT.
    Source: packages/compose-gen/specs/organisms/comparison-table.json
    Plans, or a product and its competitors, as three columns and the features as rows. A value of yes shows a check, no a dash (both with a hidden word), anything else is shown as text. Axes: highlight (none, middle column), tone, density.
    Props (p): id, title, rows, empty, labels, highlight, tone, density, landmarkLabel. *}
{var $v_id = ($p['id'] ?? null)}
{var $v_title = ($p['title'] ?? null)}
{var $v_rows = ($p['rows'] ?? null)}
{var $v_empty = ($p['empty'] ?? '')}
{var $v_labels = ($p['labels'] ?? null)}
{var $v_highlight = ($p['highlight'] ?? 'none')}
{var $v_tone = ($p['tone'] ?? 'default')}
{var $v_density = ($p['density'] ?? 'default')}
{var $v_landmarkLabel = ($p['landmarkLabel'] ?? null)}
{capture $c_16}
  {if og_t(og_eq(og_len($v_rows), 0))}
    {=og_include('blocks/empty-state.latte', ['p' => ['icon' => 'table', 'title' => $v_empty]])|noescape}
  {else}
    {capture $c_15}
      {capture $c_14}
        {capture $c_1}
          {=og_text(og_get($v_labels, ['caption']))}
        {/capture}
        {=og_include('compose/TableCaption.latte', ['class' => 'sr-only', 'children' => (string) $c_1])|noescape}
        {capture $c_7}
          {capture $c_6}
            {capture $c_2}
              {=og_text(og_get($v_labels, ['feature']))}
            {/capture}
            {=og_include('compose/TableHeadCell.latte', ['class' => 'py-4', 'attrs' => og_attrs(['scope', 'col']), 'children' => (string) $c_2])|noescape}
            {capture $c_3}
              {=og_text(og_get($v_labels, ['a']))}
            {/capture}
            {=og_include('compose/TableHeadCell.latte', ['class' => 'py-4', 'attrs' => og_attrs(['scope', 'col']), 'children' => (string) $c_3])|noescape}
            {capture $c_4}
              {=og_text(og_get($v_labels, ['b']))}
            {/capture}
            {=og_include('compose/TableHeadCell.latte', ['class' => og_s(og_cnv(['py-4', (og_t(og_eq($v_highlight, 'middle')) ? 'bg-muted' : '')])), 'attrs' => og_attrs(['scope', 'col', 'data-highlight', (og_t(og_eq($v_highlight, 'middle')) ? 'true' : 'false')]), 'children' => (string) $c_4])|noescape}
            {capture $c_5}
              {=og_text(og_get($v_labels, ['c']))}
            {/capture}
            {=og_include('compose/TableHeadCell.latte', ['class' => 'py-4', 'attrs' => og_attrs(['scope', 'col']), 'children' => (string) $c_5])|noescape}
          {/capture}
          {=og_include('compose/TableRow.latte', ['children' => (string) $c_6])|noescape}
        {/capture}
        {=og_include('compose/TableHead.latte', ['children' => (string) $c_7])|noescape}
        {capture $c_13}
          {foreach og_l($v_rows) as $v_row}
            {capture $c_12}
              {capture $c_8}
                {=og_text(og_get($v_row, ['label']))}
              {/capture}
              {=og_include('compose/TableHeadCell.latte', ['class' => og_s(og_cnv(['font-medium', (og_t(og_eq($v_density, 'compact')) ? 'py-2' : 'py-4')])), 'attrs' => og_attrs(['scope', 'row']), 'children' => (string) $c_8])|noescape}
              {capture $c_9}
                {=og_include('blocks/compare-mark.latte', ['p' => ['value' => og_get($v_row, ['a']), 'yes' => og_get($v_labels, ['yes']), 'no' => og_get($v_labels, ['no'])]])|noescape}
              {/capture}
              {=og_include('compose/TableCell.latte', ['class' => og_s(og_cnv([(og_t(og_eq($v_density, 'compact')) ? 'py-2' : 'py-4')])), 'children' => (string) $c_9])|noescape}
              {capture $c_10}
                {=og_include('blocks/compare-mark.latte', ['p' => ['value' => og_get($v_row, ['b']), 'yes' => og_get($v_labels, ['yes']), 'no' => og_get($v_labels, ['no'])]])|noescape}
              {/capture}
              {=og_include('compose/TableCell.latte', ['class' => og_s(og_cnv([(og_t(og_eq($v_density, 'compact')) ? 'py-2' : 'py-4'), (og_t(og_eq($v_highlight, 'middle')) ? 'bg-muted font-semibold' : '')])), 'children' => (string) $c_10])|noescape}
              {capture $c_11}
                {=og_include('blocks/compare-mark.latte', ['p' => ['value' => og_get($v_row, ['c']), 'yes' => og_get($v_labels, ['yes']), 'no' => og_get($v_labels, ['no'])]])|noescape}
              {/capture}
              {=og_include('compose/TableCell.latte', ['class' => og_s((og_t(og_eq($v_density, 'compact')) ? 'py-2' : 'py-4')), 'children' => (string) $c_11])|noescape}
            {/capture}
            {=og_include('compose/TableRow.latte', ['class' => 'border-t border-border', 'attrs' => og_attrs(['data-testid', 'item']), 'children' => (string) $c_12])|noescape}
          {/foreach}
        {/capture}
        {=og_include('compose/TableBody.latte', ['children' => (string) $c_13])|noescape}
      {/capture}
      {=og_include('compose/Table.latte', ['class' => 'w-full text-left text-sm', 'attrs' => og_attrs(['data-testid', 'compare']), 'children' => (string) $c_14])|noescape}
    {/capture}
    {=og_include('compose/Box.latte', ['class' => 'relative w-full overflow-x-auto', 'children' => (string) $c_15])|noescape}
  {/if}
{/capture}
{=og_include('blocks/section-frame.latte', ['p' => ['id' => $v_id, 'title' => $v_title, 'tone' => $v_tone, 'density' => $v_density, 'landmarkLabel' => $v_landmarkLabel], 'children' => og_markup($c_16)])|noescape}
